/**
 * The command log: the durable source of truth.
 *
 * The engine is deterministic, so its state is a pure function of
 * (seed, ordered inputs). The log therefore stores inputs, not state:
 * - `open`: a guest account was opened;
 * - `command`: a user's place or cancel command;
 * - `ticks`: the simulated market advanced N ticks since the previous entry,
 *   between times `from` and `at`.
 *
 * Bot orders are never logged; they are regenerated by replaying the same
 * ticks with the same seed. On startup the host replays the session's log and
 * arrives at exactly the state it had before. See docs/adr/0004-command-log.md.
 */

import type { Command } from "@marketlab/engine";
import { z } from "zod";

export type LogEntry =
  | { readonly kind: "open"; readonly accountId: string; readonly at: number }
  | { readonly kind: "ticks"; readonly count: number; readonly from: number; readonly at: number }
  | { readonly kind: "command"; readonly command: Command; readonly at: number };

const at = z.number().int().nonnegative();
const qty = z.number().int().positive();
const money = z.number().int().positive();
const place = {
  kind: z.literal("place"),
  accountId: z.string(),
  symbol: z.string(),
  side: z.enum(["buy", "sell"]),
  qty,
};

/** Validates entries read back from storage, so a corrupt row fails loudly at startup. */
export const LogEntrySchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("open"), accountId: z.string(), at }),
  z.object({ kind: z.literal("ticks"), count: z.number().int().positive(), from: at, at }),
  z.object({
    kind: z.literal("command"),
    at,
    command: z.union([
      z.object({ ...place, type: z.literal("market") }),
      z.object({ ...place, type: z.literal("limit"), limitPrice: money }),
      z.object({ ...place, type: z.literal("stop"), stopPrice: money }),
      z.object({ kind: z.literal("cancel"), accountId: z.string(), orderId: z.string() }),
    ]),
  }),
]);

export interface Session {
  readonly id: number;
  readonly seed: number;
  readonly startedAt: number;
  readonly entries: readonly LogEntry[];
}

/**
 * A point-in-time copy of the engine and its read models, taken right after
 * log entry `seq` was applied. It is an optimisation only: startup restores it
 * and replays the entries after `seq` instead of the whole log. The log remains
 * the source of truth, and a snapshot that fails its checks is ignored.
 */
export interface StoredSnapshot {
  readonly seq: number;
  /** `Exchange.stateHash()` at that point; checked again after restoring. */
  readonly stateHash: string;
  /** The serialised state, as JSON text. */
  readonly state: string;
}

export interface CommandLog {
  readonly kind: "postgres" | "memory";
  /**
   * Returns the current session with its entries, or starts a new one when the
   * latest session is older than `maxAgeMs`.
   */
  openSession(now: number, maxAgeMs: number, newSeed: number): Promise<Session>;
  /** Appends entry number `seq` (1-based, gap-free) to the session. */
  append(sessionId: number, seq: number, entry: LogEntry): Promise<void>;
  /** The session's latest snapshot, if it has one. */
  loadSnapshot(sessionId: number): Promise<StoredSnapshot | null>;
  /** Stores a snapshot, replacing the session's previous one. */
  saveSnapshot(sessionId: number, snapshot: StoredSnapshot): Promise<void>;
  close(): Promise<void>;
}

export function parseEntry(value: unknown): LogEntry {
  return LogEntrySchema.parse(value) as LogEntry;
}
